COMMANDS=set(SUB_HELP.keys())

def err(s):
    print(s, file=sys.stderr)

def need_file(path):
    if not path:
        err("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable")
        return False
    return True

def take_value(args, i, opt):
    if i+1>=len(args):
        err(f"error: The argument '{opt}' requires a value but none was supplied")
        return None, i+1, 1
    return args[i+1], i+2, 0

def parse_opts(args, specs):
    opts={}; pos=[]; i=0
    while i < len(args):
        a=args[i]
        if a in ('-h','--help'):
            opts['help']=True; i+=1
        elif a in specs:
            key, hasval = specs[a]
            if hasval:
                val,i,rc=take_value(args,i,a)
                if rc: return opts,pos,rc
                opts[key]=val
            else:
                opts[key]=True; i+=1
        elif a.startswith('-'):
            return opts,pos, unknown_arg(a, None)
        else:
            pos.append(a); i+=1
    return opts,pos,0

def unknown_arg(arg, usage):
    err(f"error: Found argument '{arg}' which wasn't expected, or isn't valid in this context")
    if usage:
        err(""); err(f"USAGE:\n    {usage}")
    err(""); err("For more information try --help")
    return 1

def missing_start(missing):
    err("error: The following required arguments were not provided:")
    for m in missing:
        err(f"    {m}")
    err(""); err("USAGE:\n    executable start [OPTIONS] --description <DESCRIPTION> --project <PROJECT>")
    err(""); err("For more information try --help")
    return 1

# ---------- main ----------
def main(argv):
    args=list(argv)
    # top-level parsing up to subcommand only
    path=os.environ.get('BARTIB_FILE') or None
    i=0
    if not args:
        print(top_help(), file=sys.stderr); return 1
    while i < len(args):
        a=args[i]
        if a in ('--version','-V'):
            print(VERSION); return 0
        if a in ('--help','-h'):
            print(top_help()); return 0
        if a == '-f':
            if i+1>=len(args):
                err("error: The argument '-f <FILE>' requires a value but none was supplied")
                return 1
            path=args[i+1]; i+=2; continue
        break
    if i>=len(args):
        print(top_help(), file=sys.stderr); return 1
    cmd=args[i]; rest=args[i+1:]
    if cmd == 'help':
        if rest and rest[0] in SUB_HELP:
            print(SUB_HELP[rest[0]]); return 0
        print(top_help()); return 0
    if cmd not in COMMANDS:
        return unknown_arg(cmd, "executable [OPTIONS] <SUBCOMMAND>")
    if any(x in ('-h','--help') for x in rest):
        print(SUB_HELP[cmd]); return 0

    # command-specific parsing/validation before file-required errors
    if cmd == 'start':
        specs={'-d':('description',True),'--description':('description',True),'-p':('project',True),'--project':('project',True),'-t':('time',True),'--time':('time',True)}
        opts,pos,rc=parse_opts(rest,specs)
        if rc: return rc
        if pos: return unknown_arg(pos[0], "executable start [OPTIONS] --description <DESCRIPTION> --project <PROJECT>")
        miss=[]
        if 'description' not in opts: miss.append('--description <DESCRIPTION>')
        if 'project' not in opts: miss.append('--project <PROJECT>')
        if miss: return missing_start(miss)
        if not need_file(path): return 1
        return cmd_start(path, opts['description'], opts['project'], opts.get('time'))
    if cmd == 'change':
        specs={'-d':('description',True),'--description':('description',True),'-p':('project',True),'--project':('project',True),'-t':('time',True),'--time':('time',True)}
        opts,pos,rc=parse_opts(rest,specs)
        if rc: return rc
        if pos: return unknown_arg(pos[0], "executable change [OPTIONS]")
        if not need_file(path): return 1
        return cmd_change(path, opts.get('description'), opts.get('project'), opts.get('time'))
    if cmd == 'continue':
        specs={'-d':('description',True),'--description':('description',True),'-p':('project',True),'--project':('project',True),'-t':('time',True),'--time':('time',True)}
        opts,pos,rc=parse_opts(rest,specs)
        if rc: return rc
        if len(pos)>1: return unknown_arg(pos[1], "executable continue [OPTIONS] [NUMBER]")
        try: num=int(pos[0]) if pos else 0
        except: return unknown_arg(pos[0], "executable continue [OPTIONS] [NUMBER]")
        if not need_file(path): return 1
        return cmd_continue(path, num, opts.get('description'), opts.get('project'), opts.get('time'))
    if cmd == 'stop':
        specs={'-t':('time',True),'--time':('time',True)}
        opts,pos,rc=parse_opts(rest,specs)
        if rc: return rc
        if pos: return unknown_arg(pos[0], "executable stop [OPTIONS]")
        if not need_file(path): return 1
        return cmd_stop(path, opts.get('time'))
    if cmd in ('cancel','current','check','sanity'):
        if rest: return unknown_arg(rest[0], f"executable {cmd}")
        if not need_file(path): return 1
        return {'cancel':cmd_cancel,'current':cmd_current,'check':cmd_check,'sanity':cmd_sanity}[cmd](path)
    if cmd == 'edit':
        specs={'-e':('editor',True),'--editor':('editor',True)}
        opts,pos,rc=parse_opts(rest,specs)
        if rc: return rc
        if pos: return unknown_arg(pos[0], "executable edit [OPTIONS]")
        if not need_file(path): return 1
        return cmd_edit(path, opts.get('editor'))
    if cmd == 'last':
        specs={'-n':('number',True),'--number':('number',True)}
        opts,pos,rc=parse_opts(rest,specs)
        if rc: return rc
        if pos: return unknown_arg(pos[0], "executable last [OPTIONS]")
        try: num=int(opts.get('number',10))
        except: num=10
        if not need_file(path): return 1
        return cmd_last(path, num)
    if cmd == 'projects':
        specs={'-c':('current',False),'--current':('current',False),'-n':('no_quotes',False),'--no-quotes':('no_quotes',False)}
        opts,pos,rc=parse_opts(rest,specs)
        if rc: return rc
        if pos: return unknown_arg(pos[0], "executable projects [FLAGS]")
        if not need_file(path): return 1
        return cmd_projects(path, bool(opts.get('current')), bool(opts.get('no_quotes')))
    if cmd == 'search':
        # clap accepts missing term and treats extra words as unexpected after first
        if len(rest)>1: return unknown_arg(rest[1], "executable search <SEARCH_TERM>")
        if not need_file(path): return 1
        return cmd_search(path, rest[0] if rest else "")
    if cmd == 'status':
        specs={'-p':('project',True),'--project':('project',True)}
        opts,pos,rc=parse_opts(rest,specs)
        if rc: return rc
        if pos: return unknown_arg(pos[0], "executable status [OPTIONS]")
        if not need_file(path): return 1
        return cmd_status(path, opts.get('project'))
    if cmd in ('list','report'):
        specs={'--today':('today',False),'--yesterday':('yesterday',False),'--current_week':('current_week',False),'--last_week':('last_week',False),'--no_grouping':('no_grouping',False),'-d':('date_raw',True),'--date':('date_raw',True),'--from':('from_raw',True),'--to':('to_raw',True),'-p':('project',True),'--project':('project',True),'--round':('round',True)}
        if cmd=='list': specs.update({'-n':('number_raw',True),'--number':('number_raw',True)})
        opts,pos,rc=parse_opts(rest,specs)
        if rc: return rc
        if pos: return unknown_arg(pos[0], f"executable {cmd} [FLAGS] [OPTIONS]")
        if not need_file(path): return 1
        if 'date_raw' in opts: opts['date']=parse_date_option(opts['date_raw'],'-d/--date')
        if 'from_raw' in opts: opts['from']=parse_date_option(opts['from_raw'],'--from')
        if 'to_raw' in opts: opts['to']=parse_date_option(opts['to_raw'],'--to')
        if 'number_raw' in opts:
            try: opts['number']=int(opts['number_raw'])
            except: opts['number']=None
        return cmd_list(path, opts) if cmd=='list' else cmd_report(path, opts)
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
