#!/usr/bin/env python3
import sys, os, re, subprocess, calendar
from dataclasses import dataclass
from datetime import datetime, date, time, timedelta
from typing import Optional, List, Tuple, Dict

VERSION = "bartib 1.1.0"
NB = "\u00a0"

@dataclass
class Activity:
    start: datetime
    end: Optional[datetime]
    project: str
    desc: str
    line_no: int
    raw: str
    valid: bool = True

@dataclass
class ParseError:
    line_no: int
    raw: str
    msg: str

# ---------- formatting helpers ----------
def fmt_dt(dt: datetime) -> str:
    return dt.strftime("%Y-%m-%d %H:%M")

def fmt_date(d: date) -> str:
    return d.strftime("%Y-%m-%d")

def fmt_time(dt: datetime) -> str:
    return dt.strftime("%H:%M")

def now_minute() -> datetime:
    n = datetime.now().replace(second=0, microsecond=0)
    return n

def duration_minutes(start: datetime, end: Optional[datetime]=None) -> int:
    if end is None:
        end = now_minute()
    return int((end - start).total_seconds() // 60)

def fmt_duration(minutes: int) -> str:
    if minutes <= 0:
        return "<1m"
    h, m = divmod(minutes, 60)
    if h:
        return f"{h}h {m:02d}m"
    return f"{m}m"

def sty(code: str, s: str) -> str:
    return f"\033[{code}m{s}\033[0m"

def underline(s: str) -> str: return sty("4", s)
def bold(s: str) -> str: return sty("1", s)
def green(s: str) -> str: return sty("32", s)
def yellow(s: str) -> str: return sty("33", s)

def pad_nb(s: str, width: int) -> str:
    return s + NB * max(0, width - len(s))

def make_table(headers: List[str], rows: List[List[Tuple[str, Optional[str]]]]) -> str:
    # rows cells are (text, style_code or None). widths are based on raw text.
    widths = [len(h) for h in headers]
    for r in rows:
        for i,(txt,_) in enumerate(r):
            if len(txt) > widths[i]: widths[i] = len(txt)
    out = "\n"
    out += " ".join(underline(pad_nb(headers[i], widths[i])) for i in range(len(headers))) + " \n"
    for r in rows:
        cells=[]
        for i,(txt,code) in enumerate(r):
            cell = pad_nb(txt, widths[i])
            if code: cell = sty(code, cell)
            cells.append(cell)
        out += " ".join(cells) + " \n"
    out += "\n"
    return out

# ---------- parsing ----------
def parse_datetime_text(s: str) -> datetime:
    return datetime.strptime(s, "%Y-%m-%d %H:%M")

def parse_activity_line(raw: str, line_no: int) -> Tuple[Optional[Activity], Optional[ParseError]]:
    line = raw.rstrip("\n")
    # Bartib's format is deliberately simple and space-sensitive.
    m = re.match(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2})(?: - (\d{4}-\d{2}-\d{2} \d{2}:\d{2}))? \| (.*) \| (.*)$", line)
    if not m:
        return None, ParseError(line_no, line, "could not parse activity")
    try:
        st = parse_datetime_text(m.group(1))
        en = parse_datetime_text(m.group(2)) if m.group(2) else None
    except Exception:
        return None, ParseError(line_no, line, "could not parse date or time of activity")
    return Activity(st, en, m.group(3), m.group(4), line_no, line), None

def read_file(path: str, warn: bool=False) -> Tuple[List[str], List[Activity], List[ParseError]]:
    if not os.path.exists(path):
        return [], [], []
    with open(path, 'r', encoding='utf-8') as f:
        content = f.read().splitlines()
    acts=[]; errs=[]
    for i,line in enumerate(content,1):
        a,e = parse_activity_line(line, i)
        if a: acts.append(a)
        else: errs.append(e)
    if warn:
        for e in errs:
            print(f"Warning: Ignoring line {e.line_no}. Please see `bartib check` for further information")
    return content, acts, errs

def activity_to_line(a: Activity) -> str:
    if a.end is None:
        return f"{fmt_dt(a.start)} | {a.project} | {a.desc}"
    return f"{fmt_dt(a.start)} - {fmt_dt(a.end)} | {a.project} | {a.desc}"

def write_activities(path: str, original: List[str], acts: List[Activity], remove_lines=set()):
    by_line = {a.line_no: activity_to_line(a) for a in acts}
    max_line = max([len(original)] + [a.line_no for a in acts])
    new=[]
    for i in range(1, max_line+1):
        if i in remove_lines:
            continue
        if i in by_line:
            new.append(by_line[i])
        elif i <= len(original):
            new.append(original[i-1])
    # append activities whose synthetic line_no is beyond current length in order
    extra = [a for a in acts if a.line_no > max_line]
    for a in extra:
        new.append(activity_to_line(a))
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        if new:
            f.write("\n".join(new) + "\n")
        else:
            f.write("")

def append_line(path: str, line: str):
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    with open(path, 'a', encoding='utf-8') as f:
        f.write(line + "\n")

# ---------- option parsers ----------
def parse_time_option(val: Optional[str], optname: str="-t/--time") -> datetime:
    n = now_minute()
    if not val:
        return n
    try:
        parts = val.split(':')
        if len(parts) != 2 or not all(p.isdigit() for p in parts):
            raise ValueError("chars")
        hh, mm = int(parts[0]), int(parts[1])
        if not (0 <= hh <= 23 and 0 <= mm <= 59):
            raise ValueError("range")
        return datetime.combine(n.date(), time(hh, mm))
    except ValueError as e:
        reason = "input is out of range" if str(e)=="range" else "input contains invalid characters"
        print(f"Can not parse \"{val}\" as time. Argument for {optname} is ignored ({reason})")
        return n

def parse_date_option(val: Optional[str], optname: str) -> Optional[date]:
    if not val: return None
    try:
        if not re.match(r"^\d{4}-\d{2}-\d{2}$", val):
            raise ValueError("chars")
        return datetime.strptime(val, "%Y-%m-%d").date()
    except ValueError as e:
        reason = "input is out of range" if re.match(r"^\d{4}-\d{2}-\d{2}$", val or "") else "input contains invalid characters"
        print(f"Can not parse \"{val}\" as date. Argument for {optname} is ignored ({reason})")
        return None

def parse_round(val: Optional[str]) -> Optional[int]:
    if not val: return None
    m = re.match(r"^(\d+)([mh])$", val)
    if not m: return None
    num = int(m.group(1))
    if num <= 0: return None
    return num * (60 if m.group(2)=='h' else 1)

def round_dt(dt: datetime, interval: Optional[int]) -> datetime:
    if not interval: return dt
    midnight = datetime.combine(dt.date(), time(0,0))
    mins = int((dt - midnight).total_seconds() // 60)
    rounded = int((mins + interval/2) // interval) * interval
    return midnight + timedelta(minutes=rounded)

# ---------- filters ----------
def week_bounds(d: date) -> Tuple[date,date]:
    start = d - timedelta(days=d.weekday())
    return start, start + timedelta(days=6)

def month_bounds(d: date) -> Tuple[date,date]:
    last = calendar.monthrange(d.year, d.month)[1]
    return date(d.year, d.month, 1), date(d.year, d.month, last)

def apply_filters(acts: List[Activity], opts: Dict) -> List[Activity]:
    n = now_minute().date()
    frm=None; to=None
    if opts.get('today'):
        frm=to=n
    elif opts.get('yesterday'):
        frm=to=n-timedelta(days=1)
    elif opts.get('current_week'):
        frm,to=week_bounds(n)
    elif opts.get('last_week'):
        s,_=week_bounds(n); frm=s-timedelta(days=7); to=s-timedelta(days=1)
    elif opts.get('date'):
        frm=to=opts['date']
    else:
        frm=opts.get('from'); to=opts.get('to')
    res=[]
    for a in acts:
        sd = a.start.date()
        if frm and sd < frm: continue
        if to and sd > to: continue
        if opts.get('project') and a.project != opts['project']: continue
        res.append(a)
    return res

def effective(a: Activity, interval: Optional[int]=None) -> Tuple[datetime, datetime, int]:
    st = round_dt(a.start, interval)
    en0 = a.end if a.end is not None else now_minute()
    en = round_dt(en0, interval)
    return st, en, duration_minutes(st, en)

# ---------- commands ----------
def cmd_check(path: str):
    original, acts, errs = read_file(path, warn=False)
    if not errs:
        print("All lines in the file have been successfully parsed as activities.")
        return 0
    print(f"Found {len(errs)} line(s) with parsing errors")
    print()
    for e in errs:
        print()
        print(e.raw)
        print(f"  -> {e.msg} (Line: {e.line_no})")
    return 0

def cmd_sanity(path: str):
    _, acts, _ = read_file(path)
    messages=[]
    stopped = [a for a in acts if a.end is not None]
    for a in stopped:
        if duration_minutes(a.start, a.end) < 0:
            messages.append(("Activity has negative duration", a))
    # overlap in chronological order by start among stopped activities with non-negative not required
    last_end=None
    for a in sorted(stopped, key=lambda x:(x.start, x.line_no)):
        if last_end is not None and a.start < last_end:
            messages.append(("Activity started before another activity ended", a))
        if a.end is not None and (last_end is None or a.end > last_end):
            last_end = a.end
    if not messages:
        print("No unusual activities.")
    else:
        for msg,a in messages:
            print(msg)
            print(f"{a.desc} (Started: {fmt_dt(a.start)}, Ended: {fmt_dt(a.end)}, Line: {a.line_no})")
            print()
    return 0

def running_activities(acts):
    return [a for a in acts if a.end is None]

def stop_running(path: str, t: datetime, print_msgs=True) -> int:
    original, acts, _ = read_file(path, warn=False)
    changed=False
    for a in acts:
        if a.end is None:
            a.end = t
            changed=True
            if print_msgs:
                print(f"Stopped activity: \"{a.desc}\" ({a.project}) started at {fmt_dt(a.start)} ({fmt_duration(duration_minutes(a.start, a.end))})")
    if changed:
        write_activities(path, original, acts)
    return 0

def cmd_stop(path: str, tval: Optional[str]):
    return stop_running(path, parse_time_option(tval), True)

def cmd_start(path: str, desc: str, project: str, tval: Optional[str]):
    t = parse_time_option(tval)
    stop_running(path, t, True)
    append_line(path, f"{fmt_dt(t)} | {project} | {desc}")
    print(f"Started activity: \"{desc}\" ({project}) at {fmt_dt(t)}")
    return 0

def cmd_cancel(path: str):
    original, acts, _ = read_file(path, warn=False)
    remove=set()
    for a in acts:
        if a.end is None:
            print(f"Canceled activity: \"{a.desc}\" ({a.project}) started at {fmt_dt(a.start)}")
            remove.add(a.line_no)
    if remove:
        write_activities(path, original, acts, remove)
    return 0

def cmd_change(path: str, desc: Optional[str], project: Optional[str], tval: Optional[str]):
    t = parse_time_option(tval)
    original, acts, _ = read_file(path, warn=False)
    changed=False
    for a in acts:
        if a.end is None:
            if desc is not None: a.desc = desc
            if project is not None: a.project = project
            a.start = t
            changed=True
            print(f"Changed activity: \"{a.desc}\" ({a.project}) started at {fmt_dt(a.start)}")
    if changed:
        write_activities(path, original, acts)
    return 0

def distinct_recent(acts: List[Activity]) -> List[Activity]:
    seen=set(); res=[]
    for a in sorted(acts, key=lambda x:(x.start, x.line_no), reverse=True):
        key=(a.desc,a.project)
        if key not in seen:
            seen.add(key); res.append(a)
    return res

def cmd_continue(path: str, number: int, desc: Optional[str], project: Optional[str], tval: Optional[str]):
    _, acts, _ = read_file(path, warn=False)
    rec = distinct_recent(acts)
    if number < 0 or number >= len(rec):
        print(f"Error: Less than {number} distinct activities have been logged yet", file=sys.stderr)
        return 1
    base = rec[number]
    d = desc if desc is not None else base.desc
    p = project if project is not None else base.project
    return cmd_start(path, d, p, tval)

def cmd_current(path: str):
    _, acts, _ = read_file(path, warn=True)
    runs = running_activities(acts)
    if not runs:
        print("No Activity is currently running")
        return 0
    rows=[]
    for a in sorted(runs, key=lambda x:(x.start,x.line_no)):
        rows.append([(fmt_dt(a.start),None),(a.desc,None),(a.project,None),(fmt_duration(duration_minutes(a.start)),None)])
    sys.stdout.write(make_table(["Started At","Description","Project","Duration"], rows))
    return 0

def list_rows(acts: List[Activity], interval: Optional[int], no_group: bool, single_day: bool) -> str:
    acts = sorted(acts, key=lambda x:(x.start,x.line_no))
    rows=[]
    for a in acts:
        st,en,dur = effective(a, interval)
        code = "32" if a.end is None else ("33" if en.date()!=st.date() else None)
        if no_group:
            started = fmt_dt(st)
        else:
            started = fmt_time(st)
        if a.end is None:
            stopped = "-"
        else:
            stopped = fmt_dt(en) if en.date()!=st.date() else fmt_time(en)
        rows.append((st.date(), [(started,code),(stopped,code),(a.desc,code),(a.project,code),(fmt_duration(dur),code)], dur))
    headers=["Started","Stopped","Description","Project","Duration"]
    if no_group or single_day:
        return make_table(headers, [r for _,r,_ in rows])
    # custom grouped table: header, blank line, group blocks
    widths=[len(h) for h in headers]
    for _,r,_ in rows:
        for i,(txt,_) in enumerate(r): widths[i]=max(widths[i],len(txt))
    out="\n" + " ".join(underline(pad_nb(headers[i], widths[i])) for i in range(5)) + " \n"
    groups=[]
    cur=None; gr=[]
    for d,r,dur in rows:
        if cur is None or d!=cur:
            if gr: groups.append((cur,gr))
            cur=d; gr=[]
        gr.append((r,dur))
    if gr: groups.append((cur,gr))
    for d,gr in groups:
        total=sum(x[1] for x in gr)
        out += "\n" + bold(f"{fmt_date(d)}\t{fmt_duration(total)}") + "\n"
        for r,_dur in gr:
            cells=[]
            for i,(txt,code) in enumerate(r):
                cell=pad_nb(txt,widths[i])
                if code: cell=sty(code, cell)
                cells.append(cell)
            out += " ".join(cells) + " \n"
    out += "\n"
    return out

def cmd_list(path: str, opts: Dict):
    _, acts, _ = read_file(path, warn=True)
    acts = apply_filters(acts, opts)
    acts = sorted(acts, key=lambda x:(x.start,x.line_no))
    if opts.get('number') is not None:
        acts = acts[-opts['number']:]
    interval=parse_round(opts.get('round'))
    single = bool(opts.get('today') or opts.get('yesterday') or opts.get('date'))
    sys.stdout.write(list_rows(acts, interval, opts.get('no_grouping',False), single))
    return 0

def cmd_projects(path: str, current: bool, no_quotes: bool):
    _, acts, _ = read_file(path, warn=True)
    if current:
        acts = [a for a in acts if a.end is None]
    for p in sorted(set(a.project for a in acts)):
        print(p if no_quotes else f'"{p}"')
    return 0

def cmd_last(path: str, num: int):
    _, acts, _ = read_file(path, warn=True)
    rec=distinct_recent(acts)[:num]
    display=list(reversed(list(enumerate(rec))))
    rows=[]
    for idx,a in display:
        rows.append([(f"[{idx}]",None),(a.desc,None),(a.project,None)])
    sys.stdout.write(make_table([" #","Description","Project"], rows))
    return 0

def cmd_search(path: str, term: str):
    _, acts, _ = read_file(path, warn=True)
    if not term:
        print("No matching activities found")
        return 0
    rec=distinct_recent(acts)
    low=term.lower()
    matches=[]
    for idx,a in enumerate(rec):
        if low in a.desc.lower() or low in a.project.lower():
            matches.append((idx,a))
    if not matches:
        print("No matching activities found")
        return 0
    rows=[]
    for idx,a in reversed(matches):
        rows.append([(f"[{idx}]",None),(a.desc,None),(a.project,None)])
    sys.stdout.write(make_table([" #","Description","Project"], rows))
    return 0

def cmd_report(path: str, opts: Dict):
    _, acts, _ = read_file(path, warn=True)
    acts = apply_filters(acts, opts)
    interval=parse_round(opts.get('round'))
    proj_desc: Dict[str, Dict[str,int]] = {}
    for a in acts:
        _,_,dur = effective(a, interval)
        proj_desc.setdefault(a.project, {})[a.desc] = proj_desc.setdefault(a.project, {}).get(a.desc,0) + dur
    entries=[]
    total=0
    for p in sorted(proj_desc):
        pdur=sum(proj_desc[p].values()); total += pdur
        entries.append((p, pdur, sorted(proj_desc[p].items())))
    labels=["Total"]
    durs=[fmt_duration(total)]
    for p,pdur,ds in entries:
        labels.append(p); durs.append(fmt_duration(pdur))
        for d,du in ds:
            labels.append("    "+d); durs.append(fmt_duration(du))
    first_w=max([len(x) for x in labels] or [len("Total")])
    dur_w=max([len(x) for x in durs] or [3])
    def line(label, dur, is_bold=False):
        s = label + "."*max(0, first_w-len(label)) + " " + dur.rjust(dur_w)
        return bold(s) if is_bold else s
    out="\n"
    for p,pdur,ds in entries:
        out += line(p, fmt_duration(pdur), True) + "\n"
        for d,du in ds:
            out += line("    "+d, fmt_duration(du), False) + "\n"
        out += "\n"
    out += line("Total", fmt_duration(total), True) + "\n\n"
    sys.stdout.write(out)
    return 0

def cmd_status(path: str, project: Optional[str]):
    _, acts, _ = read_file(path, warn=True)
    n=now_minute().date()
    def filt_range(frm,to):
        opts={'from':frm,'to':to}
        if project: opts['project']=project
        return apply_filters(acts, opts)
    def sum_dur(xs): return sum(duration_minutes(a.start, a.end if a.end else now_minute()) for a in xs)
    today=sum_dur(filt_range(n,n))
    ws,we=week_bounds(n); week=sum_dur(filt_range(ws,we))
    ms,me=month_bounds(n); month=sum_dur(filt_range(ms,me))
    runs=[a for a in acts if a.end is None and (not project or a.project==project)]
    if project:
        head = f"\033[2m\n =======\033[0m\033[3m Status for project: \033[0m\033[1m{project}\033[0m\033[2m ======= \n\033[0m"
    else:
        head = "\033[2m\n =======\033[0m\033[3m Status for \033[0m\033[1mALL\033[0m\033[3m projects \033[0m\033[2m ======= \n\033[0m"
    out=head + "\033[2;3m\n  NOW: \033[0m"
    if runs:
        a=sorted(runs,key=lambda x:(x.start,x.line_no))[0]
        if project:
            out += f"\033[1;32m{a.desc}\033[0m\033[2m ...... \033[0m\033[1m{fmt_duration(duration_minutes(a.start))}\033[0m\033[2m\n\n\033[0m"
        else:
            out += f"\033[1;32m{a.desc}\033[0m\033[2;3m on \033[0m\033[3m{a.project}\033[0m\033[2m ...... \033[0m\033[1m{fmt_duration(duration_minutes(a.start))}\033[0m\033[2m\n\n\033[0m"
    else:
        out += "\033[1m NO Activity\n\n\033[0m"
    for label,val in [("Today",today),("Current week",week),("Current month",month)]:
        dots="."*max(0, 31-len(label))
        out += f"\033[3m \033[0m\033[2;3m {label}{dots} \033[0m\033[1m{fmt_duration(val)}\033[0m\033[3m\n\033[0m"
    out += "\n"
    sys.stdout.write(out)
    return 0

def cmd_edit(path: str, editor: Optional[str]):
    ed = editor if editor is not None else os.environ.get('EDITOR','')
    try:
        # Original treats the editor as a command path plus the file argument.
        rc = subprocess.call([ed, path])
        return rc
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        return 1

